pub proof fn lemma_always_there_is_no_request_msg_to_external_from_controller(
    spec: TempPred<ClusterState>, cluster: Cluster, controller_id: int,
)
requires
    spec.entails(lift_state(cluster.init())),
    spec.entails(always(lift_action(cluster.next()))),
    cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
    cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
ensures
    spec.entails(always(lift_state(Cluster::there_is_no_request_msg_to_external_from_controller(controller_id)))),
{
    // The controller used here is `vrs_controller_model()`, which has no external model.
    // Therefore, the controller runtime can only ever emit Kubernetes requests
    // (i.e., `RequestContent::KubernetesRequest`), never `RequestContent::ExternalRequest`.
    //
    // `there_is_no_request_msg_to_external_from_controller(controller_id)` is exactly the
    // statement that no in-flight message originates from this controller and targets the
    // external host corresponding to this controller.

    let inv = Cluster::there_is_no_request_msg_to_external_from_controller(controller_id);

    // First show the invariant holds initially.
    assert_by(
        valid(spec.implies(lift_state(cluster.init()).implies(lift_state(inv)))),
        {
            // After initialization, the network contains no in-flight messages.
            // Thus the universal condition over `s.in_flight().contains(msg)` holds trivially.
        },
    );

    // Then show it is preserved by every possible step.
    // Since the controller has no external model, it cannot create messages whose
    // destination is `HostId::External(controller_id)`.
    //
    // We can use the generic temporal-logic rule `init_invariant` which combines:
    //   - holds in the initial states
    //   - preserved under each transition
    // together with the provided `spec.entails(always(lift_action(cluster.next())))`.

    // Provide the required side conditions for `init_invariant`.
    let next = cluster.next();

    assert_by(
        valid(spec.entails(always(lift_state(inv)))),
        {
            // Directly discharge the goal using `init_invariant`.
            init_invariant(spec, cluster.init(), next, inv);
        },
    );
}
}

